package com.abhiai.abhiai_backend.entity;import java.time.Instant;import java.util.UUID;import org.hibernate.annotations.CreationTimestamp;import jakarta.persistence.*;@Entity@Table(name="recommendation_signals")public class RecommendationSignal{@Id@GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id")private User user;@Column(name="signal_type",nullable=false,length=32)private String type;@Column(name="entity_type",nullable=false,length=24)private String entityType;@Column(name="entity_id",nullable=false)private UUID entityId;@CreationTimestamp@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt;protected RecommendationSignal(){}public RecommendationSignal(User u,String t,String et,UUID eid){user=u;type=t;entityType=et;entityId=eid;}}
